import React from "react";

const SlotCard = ({ slot }) => {
  const isOccupied = slot.status === "occupied";
  const bgColor = isOccupied ? "#ff4d4d" : "#4CAF50"; // red or green
  const textColor = "#fff";

  return (
    <div
      style={{
        backgroundColor: bgColor,
        color: textColor,
        borderRadius: "8px",
        padding: "16px",
        margin: "10px",
        width: "180px",
        textAlign: "center",
        boxShadow: "0 2px 6px rgba(0,0,0,0.2)",
      }}
    >
      <h3>Slot {slot.slot}</h3>
      <p>Status: {slot.status}</p>
      <p>Last Plate: {slot.plate || "-"}</p>
      <p>Time: {slot.time ? new Date(slot.time).toLocaleTimeString() : "-"}</p>
    </div>
  );
};

export default SlotCard;
